public class Query {
    public Map<String, Integer> localizedStringsPerCountry(Resource resource) {
        Map<String, Integer> counts = new HashMap<>();
        for (EObject root : resource.getContents()) {
            collectLocalizedStringsPerCountry(root, counts);
        }
        return counts;
    }

    private void collectLocalizedStringsPerCountry(EObject eObject, Map<String, Integer> counts) {
        if (eObject instanceof LOCALIZEDSTRING ls) {
            String code = ls.getCountryCode();
            if (code != null) {
                counts.put(code, counts.getOrDefault(code, 0) + 1);
            }
        }
        for (EObject child : eObject.eContents()) {
            collectLocalizedStringsPerCountry(child, counts);
        }
    }
}

