public class Query {
    public int totalLinkCount(Resource resource) {
        int count = 0;
        for (EObject root : resource.getContents()) {
            count += countLinks(root);
        }
        return count;
    }

    private int countLinks(EObject eObject) {
        int count = 0;
        if (eObject instanceof EGamaLink) {
            count++;
        }
        for (EObject child : eObject.eContents()) {
            count += countLinks(child);
        }
        return count;
    }
}

