pattern:
public class Query {
    public Set<EVariable> variablesWithBounds(Resource resource) {
        Set<EVariable> result = new HashSet<>();

        for (EObject root : resource.getContents()) {
            collectVariablesWithBounds(root, result);
        }

        return result;
    }

    private void collectVariablesWithBounds(EObject eObject, Set<EVariable> result) {
        if (eObject instanceof EVariable v) {
            if (v.getMin() != null || v.getMax() != null || v.getInit() != null) {
                result.add(v);
            }
        }

        for (EObject child : eObject.eContents()) {
            collectVariablesWithBounds(child, result);
        }
    }
}

