public class Query {
    public Set<EGamaModel> modelsWithRegionInName(Resource resource) {
        Set<EGamaModel> result = new HashSet<>();

        for (EObject root : resource.getContents()) {
            collectModelsWithRegionInName(root, result);
        }

        return result;
    }

    private void collectModelsWithRegionInName(EObject eObject, Set<EGamaModel> result) {
        if (eObject instanceof EGamaModel m) {
            String nm = m.getName();
            if (nm != null && nm.toLowerCase().contains("region")) {
                result.add(m);
            }
        }

        for (EObject child : eObject.eContents()) {
            collectModelsWithRegionInName(child, result);
        }
    }
}

