public class Query {
    public Set<EDisplay> displaysWithLinkOrLayer(Resource resource) {
        Set<EDisplay> result = new HashSet<>();
        for (EObject root : resource.getContents()) {
            collectDisplays(root, result);
        }
        return result;
    }

    private void collectDisplays(EObject eObject, Set<EDisplay> result) {
        if (eObject instanceof EDisplay) {
            EDisplay d = (EDisplay) eObject;
            boolean hasDisplayLink = d.getDisplayLink() != null;
            boolean hasLayerWithColorAndName = false;
            if (d.getLayers() != null && !d.getLayers().isEmpty()) {
                for (ELayer layer : d.getLayers()) {
                    boolean hasColor = layer.getColor() != null && !layer.getColor().isEmpty();
                    boolean hasName = layer.getName() != null && !layer.getName().isEmpty();
                    if (hasColor && hasName) {
                        hasLayerWithColorAndName = true;
                        break;
                    }
                }
            }

            if (hasDisplayLink || hasLayerWithColorAndName) {
                result.add(d);
            }
        }

        for (EObject child : eObject.eContents()) {
            collectDisplays(child, result);
        }
    }
}

