public class Query {
    public Set<Server> serversWithDefaultVariables(Resource resource) {
        Set<Server> result = new HashSet<>();
        for (EObject root : resource.getContents()) {
            collectServersWithDefaultVariables(root, result);
        }
        return result;
    }

    private void collectServersWithDefaultVariables(EObject eObject, Set<Server> result) {
        if (eObject instanceof Server s) {
            if (serverHasVariableWithDefault(s)) {
                result.add(s);
            }
        }
        for (EObject child : eObject.eContents()) {
            collectServersWithDefaultVariables(child, result);
        }
    }

    private boolean serverHasVariableWithDefault(Server s) {
        if (s.getVariables() != null) {
            for (Variable v : s.getVariables()) {
                if (v != null && v.getDefault() != null) {
                    return true;
                }
            }
        }
        return false;
    }
}

