public class Query {
    public double averageFacetsPerObject(Resource resource) {
        int totalFacets = 0;
        int totalObjects = 0;

        for (EObject root : resource.getContents()) {
            totalFacets += countFacets(root);
            totalObjects += countObjects(root);
        }

        return totalObjects == 0 ? 0.0 : (double) totalFacets / totalObjects;
    }

    private int countFacets(EObject eObject) {
        int count = 0;
        if (eObject instanceof EGamaObject eo) {
            count += eo.getFacets() != null ? eo.getFacets().size() : 0;
        }
        for (EObject child : eObject.eContents()) {
            count += countFacets(child);
        }
        return count;
    }

    private int countObjects(EObject eObject) {
        int count = (eObject instanceof EGamaObject) ? 1 : 0;
        for (EObject child : eObject.eContents()) {
            count += countObjects(child);
        }
        return count;
    }
}

