public class Query {
    public Set<IDENTIFICATION> identificationsWithIrdiOrIdentifier(Resource resource) {
        Set<IDENTIFICATION> result = new HashSet<>();
        for (EObject root : resource.getContents()) {
            collectIdentifications(root, result);
        }
        return result;
    }

    private void collectIdentifications(EObject eObject, Set<IDENTIFICATION> result) {
        if (eObject instanceof IDENTIFICATION id) {
            if (id.getIrdi() != null || id.getIdentifier() != null) {
                result.add(id);
            }
        }
        for (EObject child : eObject.eContents()) {
            collectIdentifications(child, result);
        }
    }
}

