public class Query {
    public Set<EGamaLink> linksWithSameModel(Resource resource) {
        Set<EGamaLink> result = new HashSet<>();

        for (EObject root : resource.getContents()) {
            collectLinksWithSameModel(root, result);
        }

        return result;
    }

    private void collectLinksWithSameModel(EObject eObject, Set<EGamaLink> result) {
        if (eObject instanceof EGamaLink l) {
            EGamaModel srcModel = l.getSource().getModel();
            EGamaModel tgtModel = l.getTarget().getModel();
            if (srcModel != null && srcModel.equals(tgtModel)) {
                result.add(l);
            }
        }

        for (EObject child : eObject.eContents()) {
            collectLinksWithSameModel(child, result);
        }
    }
}

