pattern:
public class Query {
    public Set<EExperiment> experimentsWithTunableParameters(Resource resource) {
        Set<EExperiment> result = new HashSet<>();

        for (EObject root : resource.getContents()) {
            collectExperimentsWithTunableParameters(root, result);
        }

        return result;
    }

    private void collectExperimentsWithTunableParameters(EObject eObject, Set<EExperiment> result) {
        if (eObject instanceof EExperiment exp) {
            boolean hasTunable = false;
            for (EParameter p : exp.getParameters()) {
                if (p != null && (p.getMin() != null || p.getMax() != null)) {
                    hasTunable = true;
                    break;
                }
            }
            if (hasTunable) {
                result.add(exp);
            }
        }

        for (EObject child : eObject.eContents()) {
            collectExperimentsWithTunableParameters(child, result);
        }
    }
}

