public class Query {
    public List<Server> serversWithLongestName(Resource resource) {
        int maxLen = 0;
        List<Server> allServers = new ArrayList<>();

        for (EObject root : resource.getContents()) {
            maxLen = Math.max(maxLen, collectMaxServerNameLength(root, allServers, 0));
        }

        // collect servers whose name length equals maxLen
        List<Server> result = new ArrayList<>();
        for (Server s : allServers) {
            if (s.getName() != null && s.getName().length() == maxLen) {
                result.add(s);
            }
        }
        // Optional: sort by name for deterministic order
        result.sort(Comparator.comparing(Server::getName, Comparator.nullsLast(String::compareTo)));
        return result;
    }

    private int collectMaxServerNameLength(EObject eObject, List<Server> acc, int current) {
        int max = current;
        if (eObject instanceof Server s) {
            acc.add(s);
            int len = s.getName() != null ? s.getName().length() : 0;
            max = Math.max(max, len);
        }
        for (EObject child : eObject.eContents()) {
            max = Math.max(max, collectMaxServerNameLength(child, acc, max));
        }
        return max;
    }
}

