public class Query {
    public Set<Server> serversWithProtocolOrDescription(Resource resource) {
        Set<Server> result = new HashSet<>();

        for (EObject root : resource.getContents()) {
            collectServers(root, result);
        }

        return result;
    }

    private void collectServers(EObject eObject, Set<Server> result) {
        if (eObject instanceof Server) {
            Server s = (Server) eObject;
            boolean hasProtocol = s.getProtocol() != null;
            boolean hasDescription = s.getDescription() != null && !s.getDescription().isEmpty();
            if (hasProtocol || hasDescription) {
                result.add(s);
            }
        }

        for (EObject child : eObject.eContents()) {
            collectServers(child, result);
        }
    }
}

