public class Query {
    public int countExperimentsInheritingSpecies(Resource resource) {
        int count = 0;
        for (EObject root : resource.getContents()) {
            count += countInheritingExperiments(root);
        }
        return count;
    }

    private int countInheritingExperiments(EObject eObject) {
        int count = 0;
        if (eObject instanceof EExperiment) {
            // In the given meta-model, EExperiment extends ESpecies.
            // If we want to specifically count only those that are also ESpecies types, we count all EExperiment instances.
            count++;
        }
        for (EObject child : eObject.eContents()) {
            count += countInheritingExperiments(child);
        }
        return count;
    }
}

