public class Query {
    public Set<Message> messagesWithTwoHeaderKeys(Resource resource) {
        Set<Message> result = new HashSet<>();

        for (EObject root : resource.getContents()) {
            collect(root, result);
        }

        return result;
    }

    private void collect(EObject eObject, Set<Message> result) {
        if (eObject instanceof Message m) {
            AbstractSchema headers = m.getHeaders();
            if (headers instanceof Schema s) {
                List<NamedSchema> namedHeaders = new ArrayList<>(s.getProperties());
                if (namedHeaders.size() >= 2) {
                    result.add(m);
                }
            }
        }

        for (EObject child : eObject.eContents()) {
            collect(child, result);
        }
    }
}

