public class Query {
    public int countUniquePropertyElsByRef(Resource resource) {
        Set<String> seenRefs = new HashSet<>();
        for (EObject root : resource.getContents()) {
            collectPropertyEls(root, seenRefs);
        }
        return seenRefs.size();
    }

    private void collectPropertyEls(EObject eObject, Set<String> seenRefs) {
        if (eObject instanceof PROPERTYELM pe) {
            if (pe.getRef() != null) {
                seenRefs.add(pe.getRef());
            }
        }
        for (EObject child : eObject.eContents()) {
            collectPropertyEls(child, seenRefs);
        }
    }
}

