public class Query {
    public Set<EGamaObject> namedObjects(Resource resource) {
        Set<EGamaObject> result = new HashSet<>();

        for (EObject root : resource.getContents()) {
            collectNamed(root, result);
        }

        return result;
    }

    private void collectNamed(EObject eObject, Set<EGamaObject> result) {
        if (eObject instanceof EGamaObject eo) {
            String name = eo.getName();
            if (name != null && !name.isEmpty()) {
                result.add(eo);
            }
        }

        for (EObject child : eObject.eContents()) {
            collectNamed(child, result);
        }
    }
}

