public class Query {
    public Set<Channel> channelsPublishingPayloadWithRequiredId(Resource resource) {
        Set<Channel> result = new HashSet<>();

        for (EObject root : resource.getContents()) {
            collectChannels(root, result);
        }

        return result;
    }

    private void collectChannels(EObject eObject, Set<Channel> result) {
        if (eObject instanceof Channel c) {
            Operation op = c.getPublish();
            if (op != null) {
                AbstractMessage am = op.getMessage();
                if (am instanceof Message m) {
                    AbstractSchema payload = m.getPayload();
                    if (payload instanceof Schema s) {
                        // check for a required property named "id"
                        for (String req : s.getRequired()) {
                            if ("id".equals(req)) {
                                result.add(c);
                                break;
                            }
                        }
                    }
                }
            }
        }

        for (EObject child : eObject.eContents()) {
            collectChannels(child, result);
        }
    }
}

