pattern:
public class Query {
    public Set<EObject> matchesAcOrPropRef(Resource resource, String acValue, String propRefValue) {
        Set<EObject> result = new HashSet<>();
        for (EObject root : resource.getContents()) {
            collectMatches(root, result, acValue, propRefValue);
        }
        return result;
    }

    private void collectMatches(EObject eObject, Set<EObject> result, String acValue, String propRefValue) {
        boolean matches = false;

        // ADVANCEDPROPERTYPATH: ac is required (1..1)
        if (eObject instanceof ADVANCEDPROPERTYPATH) {
            ADVANCEDPROPERTYPATH a = (ADVANCEDPROPERTYPATH) eObject;
            if (a.getAc() != null && a.getAc().equalsIgnoreCase(acValue)) {
                matches = true;
            }
            // also if there is at least one PROPERTYELM meeting some condition in propertys
            if (!matches) {
                for (PROPERTYELM pe : a.getPropertys()) {
                    if (pe.getRef() != null && propRefValue != null && pe.getRef().equalsIgnoreCase(propRefValue)) {
                        matches = true;
                        break;
                    }
                }
            }
        }

        // BASICPROPERTYPATH: property reference can be matched via propRef
        if (!matches && eObject instanceof BASICPROPERTYPATH) {
            BASICPROPERTYPATH b = (BASICPROPERTYPATH) eObject;
            if (b.getAc() != null && b.getAc().equalsIgnoreCase(acValue)) {
                matches = true;
            }
            if (!matches && b.getPropRef() != null && propRefValue != null) {
                matches = b.getPropRef().equalsIgnoreCase(propRefValue);
            }
        }

        if (matches) {
            result.add(eObject);
        }

        for (EObject child : eObject.eContents()) {
            collectMatches(child, result, acValue, propRefValue);
        }
    }
}
